import React from 'react';
import { StatCard } from './StatCard';
import { RevenueChart } from './RevenueChart';

interface StatData {
  label: string;
  value: number;
  change: number;
  trend: 'up' | 'down' | 'neutral';
}

interface MonthData {
  month: string;
  revenue: number;
}

const App: React.FC = () => {
  // Mock data for stats
  const stats: StatData[] = [
    {
      label: 'Revenue',
      value: 125000,
      change: 12.5,
      trend: 'up',
    },
    {
      label: 'Users',
      value: 89200,
      change: 8.2,
      trend: 'up',
    },
    {
      label: 'Orders',
      value: 4560,
      change: 15.3,
      trend: 'up',
    },
    {
      label: 'Churn',
      value: 2.3,
      change: -3.1,
      trend: 'down',
    },
  ];

  // Mock data for revenue chart
  const monthData: MonthData[] = [
    { month: 'Jan', revenue: 8000 },
    { month: 'Feb', revenue: 9500 },
    { month: 'Mar', revenue: 10200 },
    { month: 'Apr', revenue: 11500 },
    { month: 'May', revenue: 12800 },
    { month: 'Jun', revenue: 13500 },
    { month: 'Jul', revenue: 14200 },
    { month: 'Aug', revenue: 15000 },
    { month: 'Sep', revenue: 16000 },
    { month: 'Oct', revenue: 17500 },
    { month: 'Nov', revenue: 19000 },
    { month: 'Dec', revenue: 20500 },
  ];

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto space-y-8">
        <header className="text-center mb-8">
          <h1 className="text-3xl font-bold text-gray-800">Dashboard</h1>
          <p className="text-gray-600 mt-2">Performance metrics and trends</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {stats.map((stat, index) => (
            <StatCard key={index} stat={stat} />
          ))}
        </div>

        <div className="mt-10">
          <RevenueChart data={monthData} />
        </div>
      </div>
    </div>
  );
};

export default App;
```

