### StatCard.tsx
```tsx
import React from 'react';
import { ArrowUpIcon, ArrowDownIcon, ArrowRightIcon } from 'lucide-react';

interface StatCardProps {
  stat: {
    label: string;
    value: number;
    change: number;
    trend: 'up' | 'down' | 'neutral';
  };
}

const StatCard: React.FC<StatCardProps> = ({ stat }) => {
  const trendIcon = stat.trend === 'up' ? <ArrowUpIcon size={16} className="text-green-500" /> :
    stat.trend === 'down' ? <ArrowDownIcon size={16} className="text-red-500" /> :
    <ArrowRightIcon size={16} className="text-gray-400" />;

  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow duration-200">
      <div className="flex justify-between items-start mb-2">
        <h3 className="text-sm font-medium text-gray-500">{stat.label}</h3>
        <div className="flex items-center">
          {trendIcon}
          <span className={`ml-1 text-sm font-semibold ${stat.trend === 'up' ? 'text-green-600' : stat.trend === 'down' ? 'text-red-600' : 'text-gray-500'}`}>
            {stat.change > 0 ? '+' : ''}{stat.change}%
          </span>
        </div>
      </div>
      <div className="text-2xl font-bold text-gray-900">{stat.value.toLocaleString()}</div>
    </div>
  );
};

export default StatCard;
```

### RevenueChart.tsx
```tsx
import React from 'react';
import { Line } from 'recharts';

interface MonthData {
  month: string;
  revenue: number;
}

interface RevenueChartProps {
  data: MonthData[];
}

const RevenueChart: React.FC<RevenueChartProps> = ({ data }) => {
  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
      <h2 className="text-xl font-semibold text-gray-800 mb-4">Monthly Revenue</h2>
      <div className="h-64 relative">
        <Line
          dataKey="revenue"
          type="monotone"
          strokeWidth={3}
          stroke="#047857"
          dot={false}
          className="stroke-accent"
          data={data.map(d => ({ ...d, revenue: d.revenue }))} // Reuse data structure
        />
        <div className="absolute bottom-0 left-0 right-0 flex justify-between text-xs text-gray-500 px-4">
          {data.map((d, i) => (
            <div key={i} className="flex flex-col items-center">
              <div>{d.month}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default RevenueChart;
```

